G.ROOMS["zh-n07"] = {"id":"zh-n07","lang":"zh","teacher":"wang","title":"Nền tảng 7 · Độ cao thanh nhẹ","pyQuiz":true,"intro":["妈妈 朋友 姐姐 爸爸","Nghe 4 từ, chữ thứ hai đều đọc nhẹ. Đọc thanh nhẹ đúng độ cao theo thanh đứng trước, nhận ra từ có thanh nhẹ; đạt 8/10."],"introPy":"māma péngyou jiějie bàba","gram":{"t":"Độ cao thanh nhẹ","b":"Âm nhẹ \"dựa\" vào âm đứng trước.","d":"Sau thanh 1, 2: nhẹ ở mức giữa thấp (妈妈, 朋友). Sau thanh 3: nhẹ ở mức khá cao (姐姐, 我们). Sau thanh 4: nhẹ thấp nhất (爸爸, 谢谢).","ex":[["妈妈","mẹ","māma"],["朋友","bạn bè","péngyou"],["姐姐","chị","jiějie"],["我们","chúng tôi","wǒmen"],["爸爸","bố","bàba"],["谢谢","cảm ơn","xièxie"]]},"grams":[{"t":"Độ cao thanh nhẹ","b":"Âm nhẹ \"dựa\" vào âm đứng trước.","d":"Sau thanh 1, 2: nhẹ ở mức giữa thấp (妈妈, 朋友). Sau thanh 3: nhẹ ở mức khá cao (姐姐, 我们). Sau thanh 4: nhẹ thấp nhất (爸爸, 谢谢).","ex":[["妈妈","mẹ","māma"],["朋友","bạn bè","péngyou"],["姐姐","chị","jiějie"],["我们","chúng tôi","wǒmen"],["爸爸","bố","bàba"],["谢谢","cảm ơn","xièxie"]]},{"t":"Từ lặp và hậu tố 们 · 子 · 头","b":"Chữ lặp lại và các hậu tố này luôn đọc nhẹ.","d":"Động từ lặp nghĩa \"thử, một chút\": 看看 kànkan, 试试 shìshi, 想想 xiǎngxiang. Hậu tố: 我们 wǒmen, 桌子 zhuōzi, 木头 mùtou.","ex":[["看看","xem thử","kànkan"],["试试","thử xem","shìshi"],["想想","nghĩ thử","xiǎngxiang"],["桌子","cái bàn","zhuōzi"],["木头","gỗ","mùtou"],["你们","các bạn","nǐmen"]]},{"t":"Trợ từ 的 · 了 · 吗","b":"Ba trợ từ hay gặp nhất, luôn đọc nhẹ và ngắn.","d":"的 de (của): 我的书 wǒ de shū. 了 le (rồi): 好了 hǎo le. 吗 ma (không?): 好吗 hǎo ma. Đừng đọc 的 thành \"đơ\" rõ ràng: chỉ lướt qua như \"tơ\".","ex":[["我的","của tôi","wǒ de"],["好了","xong rồi","hǎo le"],["好吗","được không","hǎo ma"],["走了","đi rồi","zǒu le"],["是吗","thật à","shì ma"]]},{"t":"Thanh nhẹ đổi nghĩa","b":"Cùng chữ, đọc nhẹ hay không nhẹ là hai nghĩa khác nhau.","d":"东西 dōngxī: đông và tây. 东西 dōngxi: đồ vật. 大意 dàyì: đại ý. 大意 dàyi: sơ ý, cẩu thả. 地道 dìdào: đường hầm. 地道 dìdao: chính gốc, chuẩn. Mẹo: Gặp từ quen mà nghĩa lạ, thử đọc nhẹ âm sau xem có thành nghĩa khác không.","ex":[["东西","đồ vật","dōngxi"],["大意","sơ ý","dàyi"],["地道","chính gốc","dìdao"]]}],"items":[{"zh":"妈妈","py":"māma","vi":"mẹ","ex":"妈妈","exPy":"māma","exVi":"mẹ","w":"妈妈"},{"zh":"朋友","py":"péngyou","vi":"bạn bè","ex":"朋友","exPy":"péngyou","exVi":"bạn bè","w":"朋友"},{"zh":"姐姐","py":"jiějie","vi":"chị","ex":"姐姐","exPy":"jiějie","exVi":"chị","w":"姐姐"},{"zh":"爸爸","py":"bàba","vi":"bố","ex":"爸爸","exPy":"bàba","exVi":"bố","w":"爸爸"},{"zh":"我们","py":"wǒmen","vi":"chúng tôi","ex":"我们","exPy":"wǒmen","exVi":"chúng tôi","w":"我们"},{"zh":"桌子","py":"zhuōzi","vi":"cái bàn","ex":"桌子","exPy":"zhuōzi","exVi":"cái bàn","w":"桌子"},{"zh":"看看","py":"kànkan","vi":"xem thử","ex":"看看","exPy":"kànkan","exVi":"xem thử","w":"看看"},{"zh":"我的书","py":"wǒ de shū","vi":"sách của tôi","ex":"我的书","exPy":"wǒ de shū","exVi":"sách của tôi","w":"我的书"},{"zh":"你好吗","py":"nǐ hǎo ma","vi":"bạn khoẻ không","ex":"你好吗","exPy":"nǐ hǎo ma","exVi":"bạn khoẻ không","w":"你好吗"},{"zh":"东西","py":"dōngxi","vi":"đồ vật","ex":"东西","exPy":"dōngxi","exVi":"đồ vật","w":"东西"},{"zh":"试试","py":"shìshi","vi":"thử xem","ex":"试试","exPy":"shìshi","exVi":"thử xem","w":"试试"},{"zh":"想想","py":"xiǎngxiang","vi":"nghĩ thử","ex":"想想","exPy":"xiǎngxiang","exVi":"nghĩ thử","w":"想想"},{"zh":"我的","py":"wǒ de","vi":"của tôi","ex":"我的","exPy":"wǒ de","exVi":"của tôi","w":"我的"},{"zh":"好了","py":"hǎo le","vi":"xong rồi","ex":"好了","exPy":"hǎo le","exVi":"xong rồi","w":"好了"},{"zh":"好吗","py":"hǎo ma","vi":"được không","ex":"好吗","exPy":"hǎo ma","exVi":"được không","w":"好吗"},{"zh":"大意","py":"dàyi","vi":"sơ ý","ex":"大意","exPy":"dàyi","exVi":"sơ ý","w":"大意"},{"zh":"地道","py":"dìdao","vi":"chính gốc","ex":"地道","exPy":"dìdao","exVi":"chính gốc","w":"地道"}],"outro":"很好！Phát âm chuẩn dần rồi đấy."};
G.ROOMS["zh-n08"] = {"id":"zh-n08","lang":"zh","teacher":"wang","title":"Nền tảng 8 · Tổ hợp thanh của từ ba âm tiết","pyQuiz":true,"intro":["我很好","Nghe câu ngắn có ba chữ thanh 3: 我很好 (tôi rất khoẻ). Đọc trôi từ ba âm tiết, xử lý ba thanh 3 liền nhau, biết 啊 đổi âm theo chữ trước; đạt 8/10."],"introPy":"wǒ hěn hǎo","gram":{"t":"Từ ba âm tiết","b":"Đọc từng âm đủ thanh, chữ giữa đọc hơi nhanh hơn.","d":"图书馆 túshūguǎn (2+1+3), 飞机场 fēijīchǎng (1+1+3), 电影院 diànyǐngyuàn (4+3+4: chữ giữa là nửa thanh 3).","ex":[["图书馆","thư viện","túshūguǎn"],["大学生","sinh viên","dàxuéshēng"],["飞机场","sân bay","fēijīchǎng"],["电影院","rạp chiếu phim","diànyǐngyuàn"],["星期天","chủ nhật","xīngqītiān"],["自行车","xe đạp","zìxíngchē"]]},"grams":[{"t":"Từ ba âm tiết","b":"Đọc từng âm đủ thanh, chữ giữa đọc hơi nhanh hơn.","d":"图书馆 túshūguǎn (2+1+3), 飞机场 fēijīchǎng (1+1+3), 电影院 diànyǐngyuàn (4+3+4: chữ giữa là nửa thanh 3).","ex":[["图书馆","thư viện","túshūguǎn"],["大学生","sinh viên","dàxuéshēng"],["飞机场","sân bay","fēijīchǎng"],["电影院","rạp chiếu phim","diànyǐngyuàn"],["星期天","chủ nhật","xīngqītiān"],["自行车","xe đạp","zìxíngchē"]]},{"t":"Ba thanh 3 liền nhau","b":"Chia theo nghĩa rồi áp quy tắc 3+3 cho từng cụm.","d":"我很好 wǒ hěn hǎo → wó hén hǎo. 展览馆 zhǎnlǎnguǎn → zhán lán guǎn. 小老虎 xiǎo lǎohǔ: \"xiǎo\" đứng riêng, \"lǎohǔ\" là một cụm → xiǎo láohǔ. Mẹo: Không cần nghĩ quy tắc khi nói: nói nhanh và liền thì miệng tự đổi.","ex":[["我很好","tôi rất khoẻ","wǒ hěn hǎo"],["展览馆","nhà triển lãm","zhǎnlǎnguǎn"],["我也有","tôi cũng có","wǒ yě yǒu"],["小老虎","hổ con","xiǎo lǎohǔ"]]},{"t":"Biến âm 啊","b":"啊 cuối câu đổi âm theo chữ đứng trước, đọc liền cho thuận miệng.","d":"Sau a, o, e, i, ü → ya (来啊 lái ya). Sau u, ao, ou → wa (好啊 hǎo wa). Sau -n → na (看啊 kàn na). Sau -ng → nga (行啊 xíng nga). Mẹo: Không cần học thuộc: nói liền âm trước với \"a\" là tự ra.","ex":[["好啊","được thôi","hǎo a"],["来啊","lại đây nào","lái a"],["看啊","nhìn kìa","kàn a"],["行啊","được đấy","xíng a"]]}],"items":[{"zh":"我很好","py":"wǒ hěn hǎo","vi":"tôi rất khoẻ","ex":"我很好","exPy":"wǒ hěn hǎo","exVi":"tôi rất khoẻ","w":"我很好"},{"zh":"图书馆","py":"túshūguǎn","vi":"thư viện","ex":"图书馆","exPy":"túshūguǎn","exVi":"thư viện","w":"图书馆"},{"zh":"飞机场","py":"fēijīchǎng","vi":"sân bay","ex":"飞机场","exPy":"fēijīchǎng","exVi":"sân bay","w":"飞机场"},{"zh":"电影院","py":"diànyǐngyuàn","vi":"rạp chiếu phim","ex":"电影院","exPy":"diànyǐngyuàn","exVi":"rạp chiếu phim","w":"电影院"},{"zh":"星期天","py":"xīngqītiān","vi":"chủ nhật","ex":"星期天","exPy":"xīngqītiān","exVi":"chủ nhật","w":"星期天"},{"zh":"好啊","py":"hǎo a","vi":"được thôi","ex":"好啊","exPy":"hǎo a","exVi":"được thôi","w":"好啊"},{"zh":"大学生","py":"dàxuéshēng","vi":"sinh viên","ex":"大学生","exPy":"dàxuéshēng","exVi":"sinh viên","w":"大学生"},{"zh":"展览馆","py":"zhǎnlǎnguǎn","vi":"nhà triển lãm","ex":"展览馆","exPy":"zhǎnlǎnguǎn","exVi":"nhà triển lãm","w":"展览馆"},{"zh":"我也有","py":"wǒ yě yǒu","vi":"tôi cũng có","ex":"我也有","exPy":"wǒ yě yǒu","exVi":"tôi cũng có","w":"我也有"},{"zh":"来啊","py":"lái a","vi":"lại đây nào","ex":"来啊","exPy":"lái a","exVi":"lại đây nào","w":"来啊"},{"zh":"看啊","py":"kàn a","vi":"nhìn kìa","ex":"看啊","exPy":"kàn a","exVi":"nhìn kìa","w":"看啊"}],"outro":"很好！Phát âm chuẩn dần rồi đấy."};
G.ROOMS["zh-n09"] = {"id":"zh-n09","lang":"zh","teacher":"wang","title":"Nền tảng 9 · Nhịp đọc theo cụm nghĩa","pyQuiz":true,"intro":["我明天去学校。","Nghe câu: 我明天去学校 (Mai tôi đến trường). Đọc câu ngắn có nhịp theo cụm nghĩa, nhấn đúng chỗ, lên giọng xuống giọng đúng loại câu; đạt 8/10."],"introPy":"wǒ míngtiān qù xuéxiào","gram":{"t":"Nhịp theo cụm nghĩa","b":"Đọc theo cụm từ, không đọc từng chữ rời rạc.","d":"Một cụm thường gồm 2–4 chữ có nghĩa đi với nhau: 我 / 明天 / 去 / 学校。 Chữ cuối cụm hơi dài hơn, giữa các cụm nghỉ rất ngắn.","ex":[["我明天去学校。","Mai tôi đến trường.","wǒ / míngtiān / qù xuéxiào"],["我是越南人。","Tôi là người Việt Nam.","wǒ / shì / Yuènán rén"],["今天天气很好。","Hôm nay trời đẹp.","jīntiān / tiānqì / hěn hǎo"]]},"grams":[{"t":"Nhịp theo cụm nghĩa","b":"Đọc theo cụm từ, không đọc từng chữ rời rạc.","d":"Một cụm thường gồm 2–4 chữ có nghĩa đi với nhau: 我 / 明天 / 去 / 学校。 Chữ cuối cụm hơi dài hơn, giữa các cụm nghỉ rất ngắn.","ex":[["我明天去学校。","Mai tôi đến trường.","wǒ / míngtiān / qù xuéxiào"],["我是越南人。","Tôi là người Việt Nam.","wǒ / shì / Yuènán rén"],["今天天气很好。","Hôm nay trời đẹp.","jīntiān / tiānqì / hěn hǎo"]]},{"t":"Trọng âm trong câu","b":"Nhấn vào thông tin mới, thông tin quan trọng.","d":"Hỏi \"你是哪国人?\" (bạn người nước nào) thì trả lời nhấn vào 越南: 我是【越南】人。 Chữ được nhấn đọc to hơn, dài hơn và thanh rõ hơn. Các chữ còn lại đọc nhẹ, nhanh.","ex":[["我是越南人。","Tôi là người Việt Nam.","wǒ shì Yuènán rén"],["我喜欢喝茶。","Tôi thích uống trà.","wǒ xǐhuan hē chá"]]},{"t":"Ngữ điệu câu hỏi · câu kể · câu cảm thán","b":"Thanh điệu vẫn giữ, nhưng cả câu có thể nâng lên hoặc hạ xuống.","d":"Câu hỏi có 吗: cuối câu hơi lên nhẹ (你是学生吗？). Câu hỏi có từ để hỏi (谁, 什么, 哪儿): nhấn vào từ để hỏi, cuối câu không cần lên. Câu kể: cuối câu hạ xuống. Câu cảm thán (太好了！): nhấn mạnh, kéo dài chữ chính.","ex":[["你是学生吗？","Bạn là học sinh à?","nǐ shì xuésheng ma"],["你去哪儿？","Bạn đi đâu?","nǐ qù nǎr"],["我是老师。","Tôi là giáo viên.","wǒ shì lǎoshī"],["太好了！","Tuyệt quá!","tài hǎo le"]]}],"items":[{"zh":"我明天去学校。","py":"wǒ míngtiān qù xuéxiào","vi":"Mai tôi đến trường.","ex":"我明天去学校。","exPy":"wǒ míngtiān qù xuéxiào","exVi":"Mai tôi đến trường.","w":"我明天去学校。"},{"zh":"你好，我叫阿明。","py":"nǐ hǎo, wǒ jiào Ā Míng","vi":"Xin chào, tôi tên A Minh.","ex":"你好，我叫阿明。","exPy":"nǐ hǎo, wǒ jiào Ā Míng","exVi":"Xin chào, tôi tên A Minh.","w":"你好，我叫阿明。"},{"zh":"我是越南人。","py":"wǒ shì Yuènán rén","vi":"Tôi là người Việt Nam.","ex":"我是越南人。","exPy":"wǒ shì Yuènán rén","exVi":"Tôi là người Việt Nam.","w":"我是越南人。"},{"zh":"你是中国人吗？","py":"nǐ shì Zhōngguó rén ma","vi":"Bạn là người Trung Quốc à?","ex":"你是中国人吗？","exPy":"nǐ shì Zhōngguó rén ma","exVi":"Bạn là người Trung Quốc à?","w":"你是中国人吗？"},{"zh":"太好了！","py":"tài hǎo le","vi":"Tuyệt quá!","ex":"太好了！","exPy":"tài hǎo le","exVi":"Tuyệt quá!","w":"太好了！"},{"zh":"我们一起去吧。","py":"wǒmen yìqǐ qù ba","vi":"Chúng ta cùng đi nhé.","ex":"我们一起去吧。","exPy":"wǒmen yìqǐ qù ba","exVi":"Chúng ta cùng đi nhé.","w":"我们一起去吧。"},{"zh":"今天天气很好。","py":"jīntiān tiānqì hěn hǎo","vi":"Hôm nay trời đẹp.","ex":"今天天气很好。","exPy":"jīntiān tiānqì hěn hǎo","exVi":"Hôm nay trời đẹp.","w":"今天天气很好。"},{"zh":"我喜欢喝茶。","py":"wǒ xǐhuan hē chá","vi":"Tôi thích uống trà.","ex":"我喜欢喝茶。","exPy":"wǒ xǐhuan hē chá","exVi":"Tôi thích uống trà.","w":"我喜欢喝茶。"},{"zh":"你是学生吗？","py":"nǐ shì xuésheng ma","vi":"Bạn là học sinh à?","ex":"你是学生吗？","exPy":"nǐ shì xuésheng ma","exVi":"Bạn là học sinh à?","w":"你是学生吗？"},{"zh":"你去哪儿？","py":"nǐ qù nǎr","vi":"Bạn đi đâu?","ex":"你去哪儿？","exPy":"nǐ qù nǎr","exVi":"Bạn đi đâu?","w":"你去哪儿？"},{"zh":"我是老师。","py":"wǒ shì lǎoshī","vi":"Tôi là giáo viên.","ex":"我是老师。","exPy":"wǒ shì lǎoshī","exVi":"Tôi là giáo viên.","w":"我是老师。"}],"outro":"很好！Phát âm chuẩn dần rồi đấy."};
G.ROOMS["zh-n10"] = {"id":"zh-n10","lang":"zh","teacher":"wang","title":"Nền tảng 10 · 10 lỗi phát âm hay gặp của người Việt","pyQuiz":true,"intro":["四 十","Thử nghe lại cặp quen thuộc: 四 sì (bốn) và 十 shí (mười). Tự sửa được 10 lỗi hay gặp, đọc trôi một đoạn văn ngắn; đạt 8/10 bài kiểm tra cuối khoá."],"introPy":"sì shí","gram":{"t":"10 lỗi hay gặp của người Việt","b":"Đây là 10 lỗi giáo viên gặp nhiều nhất ở học viên Việt Nam.","d":"1. b d g đọc thành \"b đ g\" kêu → phải như \"p t c\" nhẹ. 2. Không bật hơi p t k q c ch. 3. Lẫn z c s với zh ch sh. 4. j q x đọc như \"ch, x\" tiếng Việt mà quên nâng mặt lưỡi. 5. r đọc thành l hoặc d. 6. Lẫn -n và -ng (an/ang, in/ing). 7. ü đọc thành u hoặc i. 8. Thanh 1 không đủ cao, thanh 4 không dứt khoát. 9. Đọc đủ thanh 3 khi nói nhanh, quên biến điệu 3+3. 10. e đọc thành \"e\" tiếng Việt, ian đọc \"i-an\" thay vì \"iên\".","ex":[["四是四","bốn là bốn","sì shì sì"],["十是十","mười là mười","shí shì shí"],["天","trời","tiān"],["鹅","ngỗng","é"],["日","ngày","rì"]]},"grams":[{"t":"10 lỗi hay gặp của người Việt","b":"Đây là 10 lỗi giáo viên gặp nhiều nhất ở học viên Việt Nam.","d":"1. b d g đọc thành \"b đ g\" kêu → phải như \"p t c\" nhẹ. 2. Không bật hơi p t k q c ch. 3. Lẫn z c s với zh ch sh. 4. j q x đọc như \"ch, x\" tiếng Việt mà quên nâng mặt lưỡi. 5. r đọc thành l hoặc d. 6. Lẫn -n và -ng (an/ang, in/ing). 7. ü đọc thành u hoặc i. 8. Thanh 1 không đủ cao, thanh 4 không dứt khoát. 9. Đọc đủ thanh 3 khi nói nhanh, quên biến điệu 3+3. 10. e đọc thành \"e\" tiếng Việt, ian đọc \"i-an\" thay vì \"iên\".","ex":[["四是四","bốn là bốn","sì shì sì"],["十是十","mười là mười","shí shì shí"],["天","trời","tiān"],["鹅","ngỗng","é"],["日","ngày","rì"]]},{"t":"Ôn theo lỗi của bạn","b":"App đã ghi lại những lần bạn nghe nhầm từ bài 1 tới giờ.","d":"Mở trang \"Ôn theo lỗi của bạn\" để xem 3 cặp âm bạn sai nhiều nhất và làm bài ôn riêng cho chúng. Làm xong quay lại đây học tiếp.","ex":[]},{"t":"Đọc đoạn văn","b":"Đọc trôi cả đoạn: theo cụm nghĩa, giữ thanh, nhẹ đúng chỗ.","d":"Nghe từng câu trước, rồi đọc theo. Cuối cùng đọc cả đoạn không dừng.","ex":[["我叫阿明，是越南人。","Tôi tên A Minh, là người Việt Nam.","wǒ jiào Ā Míng, shì Yuènán rén"],["我在河内工作。","Tôi làm việc ở Hà Nội.","wǒ zài Hénèi gōngzuò"],["我每天学习中文。","Ngày nào tôi cũng học tiếng Trung.","wǒ měitiān xuéxí Zhōngwén"],["我觉得声调不难。","Tôi thấy thanh điệu không khó.","wǒ juéde shēngdiào bù nán"],["只要多听多说。","Chỉ cần nghe nhiều nói nhiều.","zhǐyào duō tīng duō shuō"]]}],"items":[{"zh":"四","py":"sì","vi":"bốn","ex":"四","exPy":"sì","exVi":"bốn","w":"四"},{"zh":"十","py":"shí","vi":"mười","ex":"十","exPy":"shí","exVi":"mười","w":"十"},{"zh":"四是四，十是十。","py":"sì shì sì, shí shì shí","vi":"Bốn là bốn, mười là mười.","ex":"四是四，十是十。","exPy":"sì shì sì, shí shì shí","exVi":"Bốn là bốn, mười là mười.","w":"四是四，十是十。"},{"zh":"我叫阿明，是越南人。","py":"wǒ jiào Ā Míng, shì Yuènán rén","vi":"Tôi tên A Minh, là người Việt Nam.","ex":"我叫阿明，是越南人。","exPy":"wǒ jiào Ā Míng, shì Yuènán rén","exVi":"Tôi tên A Minh, là người Việt Nam.","w":"我叫阿明，是越南人。"},{"zh":"我在河内工作。","py":"wǒ zài Hénèi gōngzuò","vi":"Tôi làm việc ở Hà Nội.","ex":"我在河内工作。","exPy":"wǒ zài Hénèi gōngzuò","exVi":"Tôi làm việc ở Hà Nội.","w":"我在河内工作。"},{"zh":"我每天学习中文。","py":"wǒ měitiān xuéxí Zhōngwén","vi":"Ngày nào tôi cũng học tiếng Trung.","ex":"我每天学习中文。","exPy":"wǒ měitiān xuéxí Zhōngwén","exVi":"Ngày nào tôi cũng học tiếng Trung.","w":"我每天学习中文。"},{"zh":"只要多听多说。","py":"zhǐyào duō tīng duō shuō","vi":"Chỉ cần nghe nhiều nói nhiều.","ex":"只要多听多说。","exPy":"zhǐyào duō tīng duō shuō","exVi":"Chỉ cần nghe nhiều nói nhiều.","w":"只要多听多说。"},{"zh":"四是四","py":"sì shì sì","vi":"bốn là bốn","ex":"四是四","exPy":"sì shì sì","exVi":"bốn là bốn","w":"四是四"},{"zh":"十是十","py":"shí shì shí","vi":"mười là mười","ex":"十是十","exPy":"shí shì shí","exVi":"mười là mười","w":"十是十"},{"zh":"天","py":"tiān","vi":"trời","ex":"天","exPy":"tiān","exVi":"trời","w":"天"}],"outro":"很好！Phát âm chuẩn dần rồi đấy."};
